// Commands exposed by this plugin. The tauri-plugin build helper turns each into
// autogenerated `allow-<cmd>` / `deny-<cmd>` permissions (snake_case ->
// kebab-case), which `permissions/default.toml` aggregates into
// `coilbox-play:default`.
const COMMANDS: &[&str] = &[
    "play_generate_script",
    "play_export_script",
    "play_export_preset",
    "play_import_preset",
    "play_chobby_presets_find",
    "play_chobby_presets_read",
    "play_chobby_presets_write",
    "play_launch",
    "play_launch_replay",
    "play_launch_save",
    "play_cancel",
    "play_ask_lua_rules",
    "play_focus",
    "play_infolog",
    "play_system_info",
    "play_oa_find",
    "play_oa_check",
    "play_oa_launch",
    "play_oa_cancel",
];

fn main() {
    tauri_plugin::Builder::new(COMMANDS).build();
}
